window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[50]={"id":"050","numero":50,"titre":"Pathologie génito-scrotale chez le garçon et chez l'homme","objectifs":[{"id":"50-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic à partir de l’interrogatoire et de l’examen clinique des principales pathologies génito-scrotales","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"50-2","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître l’urgence de la prise en charge d’une torsion du testicule, d’une fasciiite nécrosante des organes génitaux externes, d’un paraphymosis","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"50-3","rang":"B","rubrique":"Contenu multimédia","titre":"Photographies : bourse transilluminable, bourse non transilluminable","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"50-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic de l’orchi-épidydimite","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"50-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser en cas d’orchiépidydimite","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"50-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de la prise en charge de l’orchi-épididymite","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"50-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge d’une torsion du testicule, d’une fasciite nécrosante des organes génitaux externes, d’un phymosis, d’un paraphymosis","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"50-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic de l’hydrocèle et du kyste du cordon","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"50-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications et non indications de l’imagerie devant une hydrocèle","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"50-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic du testicule non descendu","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"50-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications d’imagerie devant un testicule non descendu","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"50-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de la prise en charge de la cryptorchidie","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"50-13","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic des infections préputiales, du phimosis et du paraphimosis","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"50-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge des infections préputiales, du phimosis et du paraphimosis","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"50-15","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une torsion du cordon spermatique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":2},{"id":"50-16","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indication et les diagnostics différentiels de l’imagerie de torsion du cordon spermatique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0},{"id":"50-17","rang":"A","rubrique":"Contenu multimédia","titre":"Photographies d’un phimosis et d’un paraphimosis","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":0}],"astuces":[],"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-5-item-50-pathologie-genitoscrotale-chez-le-garcon-et-chez-lhomme","label":"urofrance.org"},{"href":"https://radiopaedia.org/articles/varicocele-1","label":"radiopaedia.org"},{"href":"https://www.sfendocrino.org","label":"sfendocrino.org"},{"href":"https://radiopaedia.org/articles/cryptorchidism","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/hydrocele-2","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/epididymitis","label":"radiopaedia.org"},{"href":"https://www.urofrance.org/sites/default/files/fileadmin/documents/data/PU/2014/3247/64834/FR/923709/index.pdf","label":"urofrance.org"},{"href":"https://www.urofrance.org/fileadmin/documents/data/PU/2010/3247/47245/FR/270706/article.html","label":"urofrance.org"},{"href":"https://radiopaedia.org/articles/testicular-appendix-1","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/testicular-torsion","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Bourse aiguë douloureuse — Douleur scrotale aiguë chez l'enfant, l'adolescent ou l'homme","detail":"<h4>CAT — Bourse aiguë douloureuse — Distinguer torsion du cordon, <span class=\"kw-clinique\">orchi-épididymite</span> et torsion d'hydatide</h4>","branches":[{"to":"q-torsion","label":"Début brutal, intense, unilatéral (terrain jeune)","color":"red"},{"to":"q-orchi-grav","label":"Début rapide + fièvre / signes urinaires / écoulement","color":"amber"}]},{"id":"q-torsion","kind":"decision","label":"Signes de torsion du cordon ? — Réflexe crémastérien aboli, testicule ascensionné/horizontalisé (Gouverneur), Prehn négatif","branches":[{"to":"t-explo","label":"Oui, ou doute (Doppler normal n'élimine pas)","color":"red"},{"to":"t-hydatide","label":"Réflexe conservé + nodule bleuté transilluminable","color":"amber"}]},{"id":"t-explo","kind":"terminal","label":"Exploration scrotale en urgence — Torsion du cordon spermatique","color":"red","detail":"<h4>Délai</h4><ul><li><span class=\"kw-clinique\">Nécrose</span> <span class=\"kw-alerte\">irréversible</span> au-delà de <span class=\"kw-chiffre\">6h</span> d'ischémie</li><li>Atrophie probable <span class=\"kw-chiffre\">> 24h</span></li></ul><h4>Traitement</h4><ul><li>Détorsion + <span class=\"kw-ttt\">orchidopexie</span> si testicule viable (3 points non résorbables)</li><li><span class=\"kw-ttt\">Orchidectomie</span> + <span class=\"kw-bio\">anatomopathologie</span> si non viable</li><li><span class=\"kw-ttt\">Orchidopexie controlatérale</span> systématique</li></ul>"},{"id":"t-hydatide","kind":"terminal","label":"AINS + repos, exploration si doute — Torsion de l'hydatide sessile de Morgagni","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Réflexe crémastérien conservé</span></li><li><span class=\"kw-clinique\">Nodule bleuté transilluminable</span> au pôle supérieur</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">AINS</span> + restriction d'activité</li><li>Exploration = <span class=\"kw-ttt\">simple exérèse</span> de l'hydatide</li><li>Doute persistant → <span class=\"kw-ttt\">scrototomie exploratrice</span> (DD cliniquement impossible)</li></ul>"},{"id":"q-orchi-grav","kind":"decision","label":"Signes de gravité ou abcès ? — Syndrome infectieux sévère, abcès à l'échographie-Doppler","branches":[{"to":"t-orchi-hosp","label":"Signes sévères / abcès","color":"red"},{"to":"q-orchi-origine","label":"Orchi-épididymite simple","color":"green"}]},{"id":"t-orchi-hosp","kind":"terminal","label":"Hospitalisation ± geste chirurgical — Orchi-épididymite compliquée","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Hospitalisation</span> si signes généraux ou locaux sévères</li><li><span class=\"kw-ttt\">Geste chirurgical</span> si <span class=\"kw-etio\">abcès, fonte purulente ou nécrose</span></li></ul>"},{"id":"q-orchi-origine","kind":"decision","label":"Orientation étiologique ? — Sexuelle (IST) ou urinaire (BGN)","branches":[{"to":"t-ist","label":"Rapport à risque, écoulement (sujet jeune)","color":"amber"},{"to":"t-iu","label":"Signes urinaires, ECBU+ (sujet âgé)","color":"amber"}]},{"id":"t-ist","kind":"terminal","label":"Antibiothérapie probabiliste IST — Origine sexuelle (sujet jeune)","color":"amber","detail":"<h4>Clinique</h4><ul><li>Sujet jeune, rapport à risque, <span class=\"kw-clinique\">écoulement urétral</span></li><li><span class=\"kw-clinique\">Signe de Prehn positif</span> (l'élévation soulage)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ceftriaxone IM</span> (1 injection) + <span class=\"kw-ttt\">doxycycline</span> <span class=\"kw-chiffre\">10 jours</span></li><li>Alternative : C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> IM + <span class=\"kw-ttt\">azithromycine</span>, ou <span class=\"kw-ttt\">ofloxacine</span></li><li>Abstinence/préservatif + <span class=\"kw-ttt\">dépistage des partenaires</span></li></ul>"},{"id":"t-iu","kind":"terminal","label":"Fluoroquinolones puis relais antibiogramme — Origine urinaire (BGN, sujet âgé)","color":"amber","detail":"<h4>Clinique</h4><ul><li>Sujet âgé, <span class=\"kw-clinique\">signes urinaires</span>, <span class=\"kw-bio\">ECBU positif</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Fluoroquinolones</span> puis relais selon <span class=\"kw-bio\">antibiogramme</span></li><li>Durée <span class=\"kw-chiffre\">≥ 14 jours</span> (<span class=\"kw-chiffre\">4–6 semaines</span> si <span class=\"kw-clinique\">prostatite</span>)</li><li><span class=\"kw-ttt\">Repos</span> + <span class=\"kw-ttt\">suspensoir</span></li></ul>"}]},"cards":[{"i":"17ea502d55bb","n":50,"o":"50-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic à partir de l’interrogatoire et de l’examen clinique des principales pathologies génito-scrotales","q":"Quelle approche adopte-t-on lors de l'interrogatoire d'un patient présentant une pathologie génito-scrotale, et quel est son objectif principal ?","a":"<p>L'interrogatoire doit être mené avec <strong>pudeur</strong>, <strong>bienveillance</strong> et <strong>professionnalisme</strong> pour établir une relation de confiance. Son objectif est de collecter un maximum d'informations sur les symptômes, leurs circonstances d'apparition, les antécédents médicaux et chirurgicaux, et les facteurs de risque, afin d'orienter le diagnostic et la prise en charge.</p>"},{"i":"5aa89d6d55e9","n":50,"o":"50-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic à partir de l’interrogatoire et de l’examen clinique des principales pathologies génito-scrotales","q":"Quels sont les éléments clés à rechercher lors de l'interrogatoire face à une douleur scrotale aiguë chez un jeune homme ?","a":"<ul><li><strong>Début</strong>: brutal ou progressif ?</li><li><strong>Intensité</strong>: forte, modérée ?</li><li><strong>Localisation</strong>: unilatérale, bilatérale ?</li><li><strong>Irradiation</strong>: aine, abdomen ?</li><li><strong>Facteurs déclenchants ou aggravants</strong>: traumatisme, effort ?</li><li><strong>Symptômes associés</strong>: fièvre, vomissements, brûlures mictionnelles, herpès, parotidite ourlienne ?</li><li><strong>Antécédents</strong>: cryptorchidie, chirurgie inguinale, infection urinaire, IST, traumatisme ?</li></ul>"},{"i":"86bf670879e6","n":50,"o":"50-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic à partir de l’interrogatoire et de l’examen clinique des principales pathologies génito-scrotales","q":"Comment doit être réalisé l'examen clinique de l'appareil génito-scrotal masculin afin d'identifier des pathologies ?","a":"<p>L'examen clinique doit être réalisé en <strong>position debout puis allongée</strong>, et toujours <strong>comparatif</strong>. Il inclut :</p><ul><li>Les <strong>organes génitaux externes</strong>: recherche d'un érythème, d'un œdème, de lésions cutanées, de malformations congénitales.</li><li>La <strong>palpation des testicules et épididymes</strong>: recherche de taille, consistance, sensibilité, masse, position.</li><li>La <strong>transillumination scrotale</strong>: pour différencier les masses solides des masses liquidiennes (hydrocèle, spermatocèle).</li><li>L'examen des <strong>fosses inguinales et fémorales</strong>: recherche de hernies.</li><li>Un <strong>examen abdominal</strong>: recherche d'une masse ou d'une douleur projetée.</li></ul>"},{"i":"a75fc8de72c3","n":50,"o":"50-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic à partir de l’interrogatoire et de l’examen clinique des principales pathologies génito-scrotales","q":"Quels sont les signes cliniques orientant vers une torsion testiculaire, urgence chirurgicale, à rechercher lors de l'examen ?","a":"<ul><li><strong>Douleur scrotale aiguë</strong>, <strong>brutale</strong>, intense, unilatérale, parfois irradiante.</li><li><strong>Ascension du testicule</strong> (signe de Prehn négatif: la douleur n'est pas soulagée par le soulèvement du testicule).</li><li><strong>Rougeur et œdème</strong> du scrotum.</li><li>Absence de réflexe crémastérien du côté affecté.</li><li>Nausées, vomissements parfois associés.</li></ul>"},{"i":"09974fd05242","n":50,"o":"50-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic du testicule non descendu","q":"Quels sont les éléments clés de l'examen clinique permettant de diagnostiquer un testicule non descendu ?","a":"<ul><li>Le patient doit être examiné en position couchée et debout, idéalement après un bain chaud, pour favoriser le relâchement musculaire.</li><li>La palpation doit être réalisée des épines iliaques antéro-supérieures vers le scrotum.</li><li>Il est important de distinguer un testicule non descendu d'un <strong>testicule ectopique</strong> (situé en dehors du trajet normal de migration) ou d'un <strong>testicule ascenseur (rétractile)</strong> qui peut être abaissé manuellement et reste dans le scrotum.</li></ul>"},{"i":"4f75d4cab340","n":50,"o":"50-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic du testicule non descendu","q":"Quels sont les examens complémentaires à réaliser pour le diagnostic positif d'un testicule non descendu ?","a":"<p>Le diagnostic de testicule non descendu est principalement <strong>clinique</strong>. Les examens complémentaires ne sont pas nécessaires pour le diagnostic positif en l'absence de palpation. En revanche, ils peuvent être utiles en cas de <strong>non palpation bilatérale</strong> ou de suspicion d'<strong>anomalie du développement sexuel (ADS)</strong>, pour rechercher un testicule cryptique ou des anomalies associées.</p>"},{"i":"c26ebb79a409","n":50,"o":"50-10","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic du testicule non descendu","q":"Comment définir cliniquement le testicule non descendu chez le garçon ?","a":"<p>Le testicule non descendu, ou <strong>cryptorchidie</strong>, est défini par l'absence du testicule dans la bourse à son examen clinique, après tentative de mobilisation manuelle.</p>"},{"i":"2d0d2a646fc8","n":50,"o":"50-13","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des infections préputiales, du phimosis et du paraphimosis","q":"Comment diagnostiquer une balanite ou une posthite (infections préputiales) chez le garçon ou l'homme ?","a":"<p>Le diagnostic de balanite (inflammation du gland) ou de posthite (inflammation du prépuce) est <strong>clinique</strong>, évoquant une infection préputiale. Il repose sur la présence de :</p><ul><li>Une <strong>rougeur</strong>, un <strong>œdème</strong> et des <strong>douleurs</strong> du gland et/ou du prépuce.</li><li>Un <strong>écoulement purulent</strong> ou séreux sous le prépuce.</li><li>Des <strong>démangeaisons</strong> ou une sensation de brûlure.</li><li>Parfois, des difficultés à décalotter.</li></ul>"},{"i":"8e15b942bcab","n":50,"o":"50-13","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des infections préputiales, du phimosis et du paraphimosis","q":"Comment diagnostiquer un paraphimosis chez le garçon ou l'homme ?","a":"<p>Le diagnostic de paraphimosis est <strong>clinique et urgent</strong>. Il se manifeste par un <strong>prépuce décalotté et bloqué</strong> en arrière du gland, formant un anneau serré qui étrangle la verge et entraîne :</p><ul><li>Un <strong>œdème</strong> du gland et du prépuce distal.</li><li>Des <strong>douleurs intenses</strong>.</li><li>Une <strong>ischémie</strong> avec un risque de nécrose du gland si non traité rapidement.</li></ul>"},{"i":"ec80b0054134","n":50,"o":"50-13","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des infections préputiales, du phimosis et du paraphimosis","q":"Comment diagnostiquer un phimosis chez le garçon ou l'homme ?","a":"<p>Le diagnostic de phimosis est <strong>clinique</strong>. Il repose sur l'<strong>impossibilité de décalotter</strong> le prépuce en arrière du sillon balano-préputial (ou gland), que la verge soit au repos ou en érection.</p>"},{"i":"ab9b4736c7f5","n":50,"o":"50-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge des infections préputiales, du phimosis et du paraphimosis","q":"Qu'est-ce qu'un paraphimosis et quelle est son urgence ?","a":"<p>Un paraphimosis est un <strong>étranglement du gland par un anneau préputial rétracté et non réductible</strong> après un décalottage, empêchant le décalottage en position physiologique. C'est une <strong>urgence urologique</strong> car il peut entraîner une ischémie et une nécrose du gland.</p>"},{"i":"c0428990bf5b","n":50,"o":"50-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge des infections préputiales, du phimosis et du paraphimosis","q":"Quelles sont les infections préputiales courantes et comment les prendre en charge ?","a":"<p>Les infections préputiales courantes sont les <strong>balanites</strong> et les <strong>balanoposthites</strong> (inflammation du gland et du prépuce). Elles sont souvent favorisées par une mauvaise hygiène ou un phimosis.</p><ul><li><strong>Principes de prise en charge</strong> :</li><ul><li><strong>Nettoyage local doux</strong> avec de l'eau et du savon.</li><li><strong>Antiseptiques locaux</strong> (ex: chlorhexidine diluée).</li><li>Si origine bactérienne suspectée : <strong>antibiotiques locaux</strong> (crème) voire oraux en cas de signes systémiques (fièvre, adénopathies).</li><li>Si origine mycosique (candida) : <strong>antifongiques locaux</strong> (crème).</li><li>En cas de balanites récidivantes associées à un phimosis : prise en charge du phimosis (crème corticoïde, plastie ou circoncision).</li></ul></ul>"},{"i":"c405d8005fd2","n":50,"o":"50-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge des infections préputiales, du phimosis et du paraphimosis","q":"Comment doit-on prendre en charge un paraphimosis ?","a":"<p>La prise en charge d'un paraphimosis est une urgence et doit être rapide :</p><ul><li><strong>Réduction manuelle immédiate</strong> : compression du gland (pendant 5-10 minutes) pour diminuer l'œdème puis tentative de réduction en faisant passer l'anneau préputial par-dessus le gland. Une anesthésie locale ou sédation peut être nécessaire.</li><li>En cas d'échec ou de paraphimosis ancien : <strong>incision dorsale de l'anneau préputial</strong> ou <strong>circoncision d'urgence</strong>.</li><li>Après réduction, si la cause est un phimosis sous-jacent, une circoncision peut être envisagée à distance.</li></ul>"},{"i":"f82b93f1ff37","n":50,"o":"50-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge des infections préputiales, du phimosis et du paraphimosis","q":"Comment définiriez-vous et comment traiteriez-vous un phimosis chez l'enfant et chez l'adulte ?","a":"<p>Un phimosis est une <strong>impossibilité de décalotter le gland</strong>. Il peut être physiologique chez le jeune enfant. La prise en charge dépend de l'âge :</p><ul><li><strong>Chez l'enfant</strong> (physiologique jusqu'à 3-4 ans) : <strong>abstention thérapeutique initiale</strong> et éducation. Si persistant ou symptomatique (balanites à répétition, dysurie), un traitement local par <strong>crème corticoïde</strong> (bétaméthasone 0,05-0,1%) 2 fois par jour pendant 1 mois est proposé en première intention. En cas d'échec ou de phimosis très serré, une <strong>plastie préputiale</strong> ou une <strong>circoncision</strong> peut être nécessaire.</li><li><strong>Chez l'adulte</strong> : souvent acquis suite à des inflammations ou traumatismes. Le traitement est chirurgical par <strong>circoncision</strong> ou <strong>plastie préputiale</strong> si le décalottage reste impossible ou symptomatique (douleur, infections).</li></ul>"},{"i":"29139b64becf","n":50,"o":"50-15","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une torsion du cordon spermatique","q":"Quels sont les principaux signes cliniques évocateurs d'une torsion du cordon spermatique ?","a":"<ul><li><strong>Douleur scrotale aiguë, intense, unilatérale et d'emblée maximale</strong>, le plus souvent d'apparition brutale.</li><li>Irradiation de la douleur fréquente vers l'abdomen ou la région inguinale.</li><li><strong>Ascension testiculaire</strong> homo-latérale ('testicule haut').</li><li><strong>Réflexe crémastérien aboli</strong> du côté atteint.</li><li>Oedème, rougeur scrotale, voire signes inflammatoires locaux évolués.</li><li>Symptômes généraux inconstants : nausées, vomissements.</li></ul>"},{"i":"2dc809e2cb63","n":50,"o":"50-15","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une torsion du cordon spermatique","q":"Quel est le signe échographique le plus spécifique d'une torsion du cordon spermatique ?","a":"<p>Le signe échographique le plus spécifique est l'<strong>absence de flux vasculaire intra-testiculaire au Doppler couleur et pulsé</strong> du testicule atteint, en comparaison avec le côté controlatéral.</p>"},{"i":"93aba32ef919","n":50,"o":"50-15","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une torsion du cordon spermatique","q":"Dans quel contexte clinique la chirurgie exploratrice scrotale doit-elle être envisagée d'emblée pour une torsion du cordon spermatique, sans attendre les résultats de l'échographie ?","a":"<p>Devant une <strong>forte suspicion clinique de torsion du cordon spermatique</strong> (douleur aiguë, ascension testiculaire, abolition du réflexe crémastérien), la chirurgie exploratrice scrotale ne doit pas être retardée par la réalisation d'une échographie, surtout si celle-ci n'est pas rapidement disponible. Le diagnostic est avant tout clinique pour ne pas perdre de temps face à l'urgence thérapeutique.</p>"},{"i":"df5df6d6a2d5","n":50,"o":"50-15","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une torsion du cordon spermatique","q":"Lors de la suspicion d'une torsion du cordon spermatique, quel est l'examen complémentaire de première intention à réaliser ?","a":"<p>L'examen complémentaire de première intention est l'<strong>échographie-Doppler testiculaire</strong>. Elle permet de visualiser l'absence ou la forte diminution de la vascularisation testiculaire du côté atteint et d'éliminer un diagnostic différentiel comme l'épididymite.</p>"},{"i":"fb92a1a85658","n":50,"o":"50-15","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une torsion du cordon spermatique","q":"Quelle est la définition d'une torsion du cordon spermatique ?","a":"<p>La torsion du cordon spermatique est une urgence chirurgicale urologique, correspondant à la <strong>rotation du testicule autour de l'axe de son pédicule vasculaire</strong>, entraînant une ischémie qui peut mener à la nécrose testiculaire.</p>"},{"i":"1cf430fc158a","n":50,"o":"50-17","u":"Contenu multimédia","t":"Photographies d’un phimosis et d’un paraphimosis","q":"Quelle est la principale complication grave d'un paraphimosis non traité chez le garçon ou l'homme ?","a":"<p>La principale complication grave d'un paraphimosis non traité est l'<strong>ischémie du gland</strong>, pouvant évoluer vers la <strong>nécrose</strong>.</p>"},{"i":"452a93e21dae","n":50,"o":"50-17","u":"Contenu multimédia","t":"Photographies d’un phimosis et d’un paraphimosis","q":"Comment se présente un paraphimosis observé à l'examen clinique chez le garçon ou l'homme ?","a":"<p>Un paraphimosis se manifeste par un <strong>prépuce rétracté derrière le gland</strong>, formant un anneau constricteur. Le gland est alors <strong>œdémateux</strong> et <strong>douloureux</strong>, potentiellement cyanique, avec un risque de nécrose par ischémie.</p>"},{"i":"bc94b9ab5676","n":50,"o":"50-17","u":"Contenu multimédia","t":"Photographies d’un phimosis et d’un paraphimosis","q":"Comment reconnaître un phimosis à l'examen clinique chez le garçon ou l'homme ?","a":"<p>Un phimosis se caractérise par l'<strong>impossibilité de décalotter</strong> le gland, c'est-à-dire de rétracter le prépuce derrière le sillon balanopréputial.</p>"},{"i":"57725ccae646","n":50,"o":"50-2","u":"Identifier une urgence","t":"Connaître l’urgence de la prise en charge d’une torsion du testicule, d’une fasciiite nécrosante des organes génitaux externes, d’un paraphymosis","q":"Quelle est l'urgence de la prise en charge d'une fasciite nécrosante des organes génitaux externes (gangrène de Fournier) ?","a":"<p>La fasciite nécrosante des organes génitaux externes (gangrène de Fournier) est une urgence vitale absolue. Elle nécessite une prise en charge multidisciplinaire immédiate comprenant une <strong>détersion chirurgicale large et agressive</strong> en urgence, associée à une antibiothérapie à large spectre.</p>"},{"i":"72f19ed519c2","n":50,"o":"50-2","u":"Identifier une urgence","t":"Connaître l’urgence de la prise en charge d’une torsion du testicule, d’une fasciiite nécrosante des organes génitaux externes, d’un paraphymosis","q":"Quelle est l'urgence de la prise en charge d'un paraphimosis ?","a":"<p>Un paraphimosis est une urgence urologique qui nécessite une prise en charge rapide. Il y a un risque d'<strong>ischémie</strong> et de <strong>nécrose</strong> du gland par compression vasculaire si la réduction manuelle ou chirurgicale n'est pas effectuée rapidement.</p>"},{"i":"f71c9d8315d1","n":50,"o":"50-2","u":"Identifier une urgence","t":"Connaître l’urgence de la prise en charge d’une torsion du testicule, d’une fasciiite nécrosante des organes génitaux externes, d’un paraphymosis","q":"Quelle est l'urgence de la prise en charge d'une torsion du testicule ?","a":"<p>La torsion du testicule est une urgence diagnostique et thérapeutique <strong>extrême</strong>. Pour une récupération complète du testicule, la détorsion chirurgicale doit être réalisée dans un délai idéal de <strong>6 heures</strong> après le début des symptômes. Chaque heure qui passe diminue significativement les chances de survie testiculaire.</p>"},{"i":"236ddb241768","n":50,"o":"50-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de l’orchi-épidydimite","q":"Quel est l'intérêt de l'échographie-doppler dans le diagnostic d'orchi-épididymite ?","a":"<p>L'échographie-doppler testiculaire permet :<ul><li>De <strong>confirmer le diagnostic</strong> en montrant une augmentation de taille de l'épididyme et/ou du testicule avec une hyperhémie (augmentation du flux vasculaire) au doppler.</li><li>D'<strong>éliminer une torsion testiculaire</strong>, qui est une urgence chirurgicale, en visualisant un flux vasculaire conservé (alors qu'il serait absent ou diminué en cas de torsion).</li><li>De rechercher des <strong>complications</strong> telles qu'un abcès.</li></ul></p>"},{"i":"f060b5a747bd","n":50,"o":"50-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de l’orchi-épidydimite","q":"Comment le diagnostic d'orchi-épididymite est-il évoqué cliniquement chez l'homme ou le garçon ?","a":"<p>Le diagnostic clinique repose sur l'association d'une <strong>douleur scrotale unilatérale</strong> (évolution subaiguë sur quelques jours), d'un <strong>gonflement de la bourse</strong> et de <strong>signes inflammatoires locaux</strong> (rougeur, chaleur). Des signes urinaires (brûlures mictionnelles, pollakiurie) ou généraux (fièvre, asthénie) peuvent être associés.</p>"},{"i":"fda8cda29b05","n":50,"o":"50-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de l’orchi-épidydimite","q":"Quels sont les éléments paracliniques clés pour confirmer le diagnostic d'orchi-épididymite ?","a":"<p>L'examen paraclinique repose sur :<ul><li>Une <strong>échographie-doppler testiculaire</strong> : elle visualise une augmentation de taille de l'épididyme (et/ou du testicule), un épaississement des tuniques et une augmentation du flux vasculaire (hyperhémie) au doppler.</li><li>Un <strong>examen cytobactériologique des urines (ECBU)</strong> et potentiellement une <strong>recherche de CT/NG</strong> (Chlamydia trachomatis/Neisseria gonorrhoeae) sur les premières urines ou par auto-prélèvement urétral, compte tenu de la cause fréquente d'IST chez l'homme jeune.</li><li>Une <strong>biologie sanguine</strong> peut montrer un syndrome inflammatoire (hyperleucocytose, CRP élevée).</li></ul></p>"},{"i":"1bfb1f24dd74","n":50,"o":"50-6","u":"Prise en charge","t":"Connaître les modalités de la prise en charge de l’orchi-épididymite","q":"Quels sont les principes du traitement non-antibiotique de l'orchi-épididymite aiguë ?","a":"<ul><li><strong>Repos au lit</strong>.</li><li><strong>Antalgiques</strong> et <strong>anti-inflammatoires non stéroïdiens (AINS)</strong> si non contre-indiqués.</li><li><strong>Suscension scrotale</strong> pour soulager la douleur.</li></ul>"},{"i":"3235a78678b2","n":50,"o":"50-6","u":"Prise en charge","t":"Connaître les modalités de la prise en charge de l’orchi-épididymite","q":"Quelle est la durée usuelle du traitement antibiotique d'une orchi-épididymite aiguë chez l'adulte ?","a":"<p>La durée du traitement antibiotique est généralement de <strong>10 à 14 jours</strong> pour une orchi-épididymite aiguë chez l'adulte.</p>"},{"i":"44723cf84a99","n":50,"o":"50-6","u":"Prise en charge","t":"Connaître les modalités de la prise en charge de l’orchi-épididymite","q":"Comment doit être débuté le traitement antibiotique d'une orchi-épididymite aiguë avant d'avoir les résultats microbiologiques ?","a":"<p>Le traitement antibiotique en cas d'orchi-épididymite aiguë doit être débuté de manière <strong>probabiliste</strong>, c'est-à-dire avant d'avoir les résultats microbiologiques, et adapté ensuite si nécessaire.</p>"},{"i":"5e35fa216999","n":50,"o":"50-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de l’hydrocèle et du kyste du cordon","q":"Comment le diagnostic de kyste du cordon est-il confirmé chez le garçon ou l'homme ?","a":"<p>Le diagnostic de kyste du cordon est avant tout <strong>clinique</strong>. La palpation permet de sentir une masse kystique, bien délimitée, mobile et le plus souvent indolore, située le long du cordon spermatique.</p><p>Une <strong>échographie scrotale</strong> est l'examen complémentaire de choix. Elle permet de :</p><ul><li>Confirmer la <strong>nature liquidienne</strong> de la masse.</li><li>Préciser sa <strong>taille</strong> et sa <strong>localisation</strong> exacte le long du cordon.</li><li>Exclure d'autres diagnostics différentiels, notamment une hernie inguinale ou une autre masse solide.</li></ul>"},{"i":"c8035e73a7ff","n":50,"o":"50-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de l’hydrocèle et du kyste du cordon","q":"Quelles sont les caractéristiques cliniques du kyste du cordon chez le garçon ou l'homme ?","a":"<p>Le kyste du cordon, ou kyste du cordon spermatique, se manifeste cliniquement par :</p><ul><li>Une <strong>masse scrotale ou inguinale</strong>, généralement de petite taille, <strong>indolore</strong>, mobile et de consistance molle ou élastique.</li><li>Elle est souvent découverte fortuitement ou lors d'un examen clinique.</li><li>Contrairement à l'hydrocèle, ce kyste est habituellement <strong>bien délimité</strong> et le testicule est facilement palpable à côté.</p></li></ul>"},{"i":"fe27e3c89704","n":50,"o":"50-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de l’hydrocèle et du kyste du cordon","q":"Comment établit-on le diagnostic positif de l'hydrocèle chez le garçon ou l'homme ?","a":"<p>Le diagnostic positif de l'hydrocèle est principalement <strong>clinique</strong>. On retrouve :</p><ul><li>Une <strong>augmentation de volume scrotale</strong>, non douloureuse, progressive et transilluminable à la lumière.</li><li>La palpation met en évidence une <strong>masse liquidienne</strong> autour du testicule, qui est généralement difficile à palper de manière distincte.</li><li>La <strong>transillumination</strong> est le signe clé : la masse est claire et homogène à la lumière.</li></ul><p>Une <strong>échographie scrotale</strong> peut confirmer la nature liquidienne et exclure d'autres pathologies.</p>"}]};